CREATE POLICY "poll_options update author or mod" ON public.forum_poll_options FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.forum_polls p JOIN public.forum_topics t ON t.id = p.topic_id WHERE p.id = forum_poll_options.poll_id AND (t.author_id = auth.uid() OR public.is_forum_moderator(auth.uid(), t.board_id)))) WITH CHECK (EXISTS (SELECT 1 FROM public.forum_polls p JOIN public.forum_topics t ON t.id = p.topic_id WHERE p.id = forum_poll_options.poll_id AND (t.author_id = auth.uid() OR public.is_forum_moderator(auth.uid(), t.board_id))));
GRANT UPDATE ON public.forum_poll_options TO authenticated;